// Fan out every email attachment into its own item, keeping email context for the audit trail.
const out = [];
for (const [i, email] of $('Intake · Watch AP Inbox').all().entries()) {
  for (const file of Object.values(email.binary || {})) {
    out.push({
      json: {
        fileName: file.fileName,
        mimeType: file.mimeType,
        email: {
          message_id: email.json.id,
          thread_id: email.json.threadId,
          from: email.json.from?.text ?? email.json.from ?? null,
          subject: email.json.subject ?? null,
          received_at: email.json.date ?? null,
        },
      },
      binary: { data: file },
      pairedItem: { item: i },
    });
  }
}
return out;

