// Finance controls: parse the AI record, run reconciliation checks, detect duplicates and assign a routing decision.
// Duplicate keys live in workflow static data, which n8n persists for active (production) executions only.
const cfg = $('Config · Pipeline Settings').first().json;
const store = $getWorkflowStaticData('global');
store.processedKeys = store.processedKeys || [];
const seen = new Set(store.processedKeys);

const toNum = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Math.round(Number(v) * 100) / 100);
const near = (a, b) => Math.abs(a - b) <= Math.max(cfg.amountTolerance, Math.abs(b) * 0.005);
const text = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
const keyPart = (v) => String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const isIsoDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(v || '') && !isNaN(Date.parse(v));

const results = [];
for (const [i, item] of $input.all().entries()) {
  const source = $('Intake · Split Attachments').itemMatching(i).json;
  const archive = $('Archive · Store Original in Drive').itemMatching(i).json;
  const issues = [];

  let data = item.json.output;
  if (typeof data === 'string') {
    try { data = JSON.parse(data.replace(/```json\s*|```/g, '').trim()); } catch (e) { data = null; }
  }
  if (!data || typeof data !== 'object') {
    issues.push('AI extraction failed or returned invalid JSON' + (item.json.error ? `: ${item.json.error}` : ''));
    data = {};
  }

  const vendor = data.vendor || {};
  const inv = data.invoice || {};
  const t = data.totals || {};
  const meta = data.extraction || {};
  const lines = (Array.isArray(data.line_items) ? data.line_items : []).map((l, idx) => ({
    line_number: idx + 1,
    description: text(l.description),
    sku: text(l.sku),
    quantity: toNum(l.quantity),
    unit_price: toNum(l.unit_price),
    tax_rate: toNum(l.tax_rate),
    line_total: toNum(l.line_total),
  }));
  const totals = {
    subtotal: toNum(t.subtotal),
    tax_total: toNum(t.tax_total) ?? 0,
    shipping_total: toNum(t.shipping_total) ?? 0,
    discount_total: toNum(t.discount_total) ?? 0,
    total: toNum(t.total),
  };

  // 1. Required fields
  if (!text(vendor.name)) issues.push('Missing vendor name');
  if (cfg.requireTaxId && !text(vendor.tax_id)) issues.push('Missing vendor tax ID');
  if (!text(inv.invoice_number)) issues.push('Missing invoice number');
  if (!isIsoDate(inv.invoice_date)) issues.push('Missing or invalid invoice date');
  if (!(totals.total > 0)) issues.push('Missing or non-positive total');

  // 2. Arithmetic reconciliation (supports net and gross line pricing)
  const lineSum = toNum(lines.reduce((sum, l) => sum + (l.line_total || 0), 0));
  if (!lines.length) issues.push('No line items extracted');
  else if (totals.subtotal !== null && !near(lineSum, totals.subtotal) && !(totals.total && near(lineSum, totals.total))) {
    issues.push(`Line items (${lineSum}) do not reconcile to subtotal (${totals.subtotal})`);
  }
  const expected = toNum((totals.subtotal ?? lineSum) + totals.tax_total + totals.shipping_total - totals.discount_total);
  if (totals.total > 0 && !near(expected, totals.total)) {
    issues.push(`Subtotal + tax + shipping - discount (${expected}) does not equal total (${totals.total})`);
  }

  // 3. Date sanity
  if (isIsoDate(inv.invoice_date) && Date.parse(inv.invoice_date) > Date.now() + 86400000) issues.push('Invoice date is in the future');
  if (isIsoDate(inv.due_date) && isIsoDate(inv.invoice_date) && inv.due_date < inv.invoice_date) issues.push('Due date precedes invoice date');

  // 4. Document type and model confidence
  if (!['invoice', 'receipt'].includes(meta.document_type)) issues.push(`Document type "${meta.document_type || 'unknown'}" requires manual handling`);
  if (typeof meta.confidence === 'number' && meta.confidence < cfg.confidenceThreshold) {
    issues.push(`AI confidence ${meta.confidence} below threshold ${cfg.confidenceThreshold}`);
  }

  // 5. Duplicate detection on vendor identity + invoice number
  const hasKey = keyPart(vendor.tax_id || vendor.name) && keyPart(inv.invoice_number);
  const invoiceKey = hasKey
    ? `${keyPart(vendor.tax_id || vendor.name)}-${keyPart(inv.invoice_number)}`
    : `UNKEYED-${$execution.id}-${i}`;
  const isDuplicate = hasKey && seen.has(invoiceKey);
  if (hasKey && !isDuplicate) { seen.add(invoiceKey); store.processedKeys.push(invoiceKey); }

  let decision = 'AUTO_APPROVED';
  if (isDuplicate) decision = 'DUPLICATE';
  else if (issues.length) decision = 'NEEDS_REVIEW';
  else if (totals.total >= cfg.approvalThreshold) decision = 'APPROVAL_REQUIRED';

  results.push({
    json: {
      invoice_key: invoiceKey,
      decision,
      issues,
      warnings: Array.isArray(meta.warnings) ? meta.warnings : [],
      vendor_name: text(vendor.name),
      vendor_tax_id: text(vendor.tax_id),
      vendor_address: text(vendor.address),
      vendor_email: text(vendor.email),
      bill_to_name: text(data.bill_to?.name),
      invoice_number: text(inv.invoice_number),
      invoice_date: text(inv.invoice_date),
      due_date: text(inv.due_date),
      po_number: text(inv.po_number),
      payment_terms: text(inv.payment_terms),
      currency: text(inv.currency) || cfg.defaultCurrency,
      expense_category: data.classification?.expense_category || 'Other',
      ...totals,
      line_items: lines,
      line_item_count: lines.length,
      document_type: meta.document_type || 'unknown',
      confidence: meta.confidence ?? null,
      file_name: source.fileName,
      email: source.email,
      drive_file_id: archive.id,
      drive_link: archive.id ? `https://drive.google.com/file/d/${archive.id}/view` : null,
      execution_id: $execution.id,
      processed_at: $now.toISO(),
    },
    pairedItem: { item: i },
  });
}

store.processedKeys = store.processedKeys.slice(-10000);
return results;

