// Merge the Slack approval outcome back onto the validated invoice record.
const invoice = $('Validate · Apply Business Rules').item.json;
const approved = $json.data?.approved;
return {
  json: {
    ...invoice,
    status: approved === true ? 'APPROVED' : approved === false ? 'REJECTED' : 'APPROVAL_TIMEOUT',
    approval_channel: 'Slack',
    approval_at: $now.toISO(),
  },
};

// Normalise every branch (auto-approved, approval outcome, needs review) into one ledger record.
const record = { ...$json };
if (!record.status) record.status = record.decision === 'AUTO_APPROVED' ? 'APPROVED' : 'NEEDS_REVIEW';
record.issues_text = (record.issues || []).join('; ');
record.warnings_text = (record.warnings || []).join('; ');

const icon = { APPROVED: ':white_check_mark:', REJECTED: ':no_entry:', APPROVAL_TIMEOUT: ':hourglass:', NEEDS_REVIEW: ':warning:' }[record.status] || ':page_facing_up:';
const amount = `${record.currency} ${Number(record.total || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`;
record.slack_message = [
  `${icon} *${record.status.replace('_', ' ')}* · ${record.vendor_name || 'Unknown vendor'} · ${record.invoice_number || 'no invoice #'}`,
  `*Amount:* ${amount}   *Category:* ${record.expense_category}   *Due:* ${record.due_date || 'n/a'}`,
  record.issues_text ? `*Issues:* ${record.issues_text}` : null,
  record.drive_link ? `<${record.drive_link}|Open original document>` : null,
].filter(Boolean).join('\n');

return { json: record };

// One ledger row per invoice line, keyed for idempotent upserts.
return $input.all().flatMap(({ json: inv }) =>
  (inv.line_items || []).map((line) => ({
    json: {
      line_id: `${inv.invoice_key}-${String(line.line_number).padStart(3, '0')}`,
      invoice_key: inv.invoice_key,
      invoice_number: inv.invoice_number,
      vendor_name: inv.vendor_name,
      currency: inv.currency,
      expense_category: inv.expense_category,
      ...line,
    },
  }))
);
